def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the full-width and full-height divider lines.
    div_color = None
    divider_rows = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0:
            divider_rows.append(r)
            div_color = row[0]

    divider_cols = []
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and col[0] != 0:
            divider_cols.append(c)
            div_color = col[0]

    def intervals(size, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    row_blocks = intervals(h, divider_rows)
    col_blocks = intervals(w, divider_cols)

    # The repeated figure is the nonempty pattern in a block other than
    # the first column; the first-column blocks provide the row colors.
    pattern = None
    for ri, (r0, r1) in enumerate(row_blocks):
        for ci, (c0, c1) in enumerate(col_blocks):
            if ci == 0:
                continue
            cells = [
                [grid[r][c] for c in range(c0, c1)]
                for r in range(r0, r1)
            ]
            points = [(r, c) for r in range(r1-r0) for c in range(c1-c0)
                      if cells[r][c] not in (0, div_color)]
            if points:
                pattern = [[cells[r][c] != 0 for c in range(c1-c0)]
                           for r in range(r1-r0)]
                break
        if pattern is not None:
            break

    if pattern is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    colors = []
    for r0, r1 in row_blocks:
        counts = {}
        for r in range(r0, r1):
            for c in range(col_blocks[0][0], col_blocks[0][1]):
                value = grid[r][c]
                if value not in (0, div_color):
                    counts[value] = counts.get(value, 0) + 1
        colors.append(max(counts, key=counts.get) if counts else 0)

    for ri, (r0, r1) in enumerate(row_blocks):
        for ci, (c0, c1) in enumerate(col_blocks):
            for dr in range(r1-r0):
                for dc in range(c1-c0):
                    out[r0+dr][c0+dc] = (
                        colors[ri] if pattern[dr][dc] else 0
                    )

    return out
